contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint amount1, uint amount2) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount1) + (amount2)); require(amount1 <= 1000000000000000000000000000000); require(amount2 <= 1000000000000000000000000000000);
        require(address(this).balance >= amount1 + amount2, "not enough balance");

        uint balBefore = address(c).balance;
        c.deposit{value: amount1}(); if (__ESBMC_reverted()) return;
        c.deposit{value: amount2}(); if (__ESBMC_reverted()) return;
        uint balAfterDeposits = address(c).balance;

        c.withdrawAll(); if (__ESBMC_reverted()) return;

        uint afterWithdraw = address(c).balance;

        assert(balAfterDeposits == balBefore + amount1 + amount2 && afterWithdraw == balAfterDeposits - amount1 - amount2 && afterWithdraw >= balBefore);
    }

    receive() external payable {}
}

